import{_ as t,d as o,e as a,x as n}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"A.6 HV06 Drive–Uptake Chain (Full Interface Card)","description":"","frontmatter":{"title":"A.6 HV06 Drive–Uptake Chain (Full Interface Card)","xkChars":0,"xkWords":1175},"headers":[],"relativePath":"en/theory/appendix-a/a-06.md","filePath":"en/theory/appendix-a/a-06.md"}'),i={name:"en/theory/appendix-a/a-06.md"};function r(d,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<div class="theory-source"><h1 id="section-a-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.6</span><span class="xk-num__gap"></span></span>HV06 Drive–Uptake Chain (Full Interface Card) <a class="header-anchor" href="#section-a-6" aria-label="Permalink to &quot;A.6 HV06 Drive–Uptake Chain (Full Interface Card) {#section-a-6}&quot;">​</a></h1><p>A. Identity, Proposition, and Scope</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Interface ID (<code>id</code>)</td><td>HV06</td></tr><tr><td>Qualified ID (<code>qualified_id</code>)</td><td><code>human_variable:HV06</code></td></tr><tr><td>Name (<code>name</code>)</td><td>Drive–Uptake Chain</td></tr><tr><td>Claim type (<code>claim_type</code>)</td><td>H</td></tr><tr><td>Contract role (<code>contract_role</code>)</td><td><code>human_variable_interface</code></td></tr><tr><td>Proposition (<code>proposition</code>)</td><td>For the chain from orientation and generation to execution, maintenance, and repayment, register channels, resources, costs, responsibilities, and lags segment by segment.</td></tr><tr><td>Scope (<code>scope</code>)</td><td>Human collective action, projects, organizations, and institutional operations</td></tr><tr><td>Conditions for suspension (<code>pause_condition</code>)</td><td>Enthusiasm, vision, or commands are used in place of evidence about uptake and repayment</td></tr></tbody></table></div><p>B. Formal Dependencies and Limits on Conclusions</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Inferential dependencies (<code>inferential_requires</code>)</td><td>None (empty set)</td></tr><tr><td>Protocol dependencies (<code>protocol_requires</code>)</td><td>1. EVIDENCE<br>2. SOURCE</td></tr><tr><td>Qualification/specialization (<code>specializes</code>)</td><td>None (empty set)</td></tr><tr><td>References to applicable objects (<code>applies_to</code>)</td><td>None (empty set)</td></tr><tr><td>Conditional support routes (<code>conditional_support_routes</code>)</td><td>1. route_id=HV06-R0-segment-map;<br>claim_level=descriptive_classification;<br>when=The inputs, outputs, delay, loss, interruptions, resources, costs, and boundaries of at least one chain segment can be observed;<br>additional_inferential_requires=None (empty set);<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register local chain segments, missing bridges, time lags, losses, points of interruption, and positions bearing costs;<br>result_ceiling=Do not claim a complete chain or effective channel based on a single segment or language about drive.<br>2. route_id=HV06-R1-complete-chain-composition;<br>claim_level=descriptive_classification;<br>when=The three interface records for orientation, generation, and uptake can be linked segment by segment in a common mapping of object, scale, window, and quantities;<br>additional_inferential_requires=human_variable:HV03, human_variable:HV04, human_variable:HV05;<br>additional_protocol_requires=None (empty set);<br>allowed_conclusion=Register the complete candidate drive–uptake chain and evidence coverage for each segment;<br>result_ceiling=Composition of a candidate chain only. Complete interface records do not establish that each segment has a causal effect.<br>3. route_id=HV06-R2-effective-channel;<br>claim_level=mechanism_explanation;<br>when=The complete candidate chain has been assembled and an eligible G2-instance supports the specified channel. Correspondence within the same case, shared scope of support, joint response, temporal order, capacity, and the endpoint outcome must also suffice to support the whole-chain effect in question. Multiplying average effects on the edges does not suffice;<br>additional_inferential_requires=human_variable:HV03, human_variable:HV04, human_variable:HV05, G2-instance;<br>additional_protocol_requires=CAUSAL, E4;<br>allowed_conclusion=Register the effective drive–uptake channel, losses, and mechanisms of interruption for the tested segments and window;<br>result_ceiling=Do not infer intertemporal reproduction, responsibility, normative justification, or authorization to act from one pass through the chain.</td></tr><tr><td>Permitted inferences (<code>allowed_inference</code>)</td><td>1. Bottlenecks in the chain. 2. Disconnection between drive and uptake. 3. Hidden repayment</td></tr><tr><td>Prohibited leaps (<code>prohibited_leap</code>)</td><td>1. Equating strong drive with sustainability<br>2. Attributing failure to lack of willingness<br>3. Assuming those taking up the work should fill gaps on their own</td></tr></tbody></table></div><p>C. Nine-Axis Scale and Object Contract</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Nine-axis scale profile (<code>scale_profile</code>)</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;. A=Aggregation level covers events at individual links, cases involving chains, the population of similar chains, distributions of inputs and outputs, and aggregation rules. X=Spatial extent covers sites of action, project or organizational boundaries, digital spaces for collaboration, and spillovers across domains. T=Time span covers windows for initiation, maintenance, interruption, and recovery, and cycles across periods. O=Organizational level covers initiating roles, execution teams, organizations, institutions, and governance ecologies. C=Causal level covers events at links, mechanisms of interaction among drive, resources, and tasks, meso-level uptake chains, institutional arrangements, and systemic conditions. R=Resolution covers original records of tasks and resources, sequences of links, cases involving chains, loss distributions, performance metrics, and summaries. Record compression loss as well. I=Scope of influence covers positions of direct initiation and uptake, positions of indirect benefit or cost, second-order spillovers, and impacts across domains and generations. N=Network topology scope covers chains of dependency, alternative paths, bottlenecks, feedback connections, and bridges across domains. J=Scope of jurisdiction and authorization requires separate authorization records for adopting goals, assigning tasks, committing resources, stopping, and trials. Mark positions across the axes for each segment</td></tr><tr><td>Effective object (<code>effective_object</code>)</td><td>A traceable chain that converts orientation and generation into sustained action</td></tr><tr><td>Scale invariants (<code>scale_invariants</code>)</td><td>1. The chain of orientation, generation, uptake, resources, costs, and responsibility</td></tr><tr><td>Required additions for scale elevation (<code>required_scale_additions</code>)</td><td>1. Bridges across levels<br>2. Aggregation loss<br>3. Carryover of responsibility<br>4. Protection floor</td></tr><tr><td>What changes with scale (<code>changing_semantics</code>)</td><td>1. Nodes, channels, and bottlenecks can change with organizational scale</td></tr><tr><td>Inapplicable objects (<code>non_applicable_objects</code>)</td><td>1. Nonhuman processes without intentional drive or human uptake</td></tr><tr><td>Prohibited elevations (<code>forbidden_elevation</code>)</td><td>1. Treating local drive or a single node as directly representative of the complete chain</td></tr></tbody></table></div><p>D. State, Evidence, and Variable Flows</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>State set (<code>state</code>)</td><td>1. Connected end to end<br>2. Lagging<br>3. Overloaded<br>4. Disrupted<br>5. Replaced</td></tr><tr><td>Observables (<code>observables</code>)</td><td>1. Records of the anchor being translated into tasks, budgets, rules, or schedules<br>2. Inputs, outputs, delay, loss, and points of interruption for each segment<br>3. Capacity of people taking up the work, stopping, and changes in alternative paths<br>4. Actual contribution of chain outputs to the target outcome</td></tr><tr><td>Evidence requirements (<code>evidence</code>)</td><td>1. Resource flows<br>2. Task and maintenance records<br>3. Repayment and costs<br>4. Time lags</td></tr><tr><td>Input dependencies and interface content (<code>input_dependencies</code>)</td><td>1. Orientation anchor. 2. Generative node. 3. Uptake layer</td></tr><tr><td>Output effects and variable flows (<code>output_effects</code>)</td><td>1. Action outcomes. 2. Load. 3. Feedback and traces of evolution</td></tr><tr><td>Time window and lag (<code>time_window_and_lag</code>)</td><td>Register lags in initiation, transmission, maintenance, and repayment segment by segment</td></tr><tr><td>Uncertainty (<code>uncertainty</code>)</td><td>Record breaks, alternative channels, and repayment outside the boundary</td></tr><tr><td>Local exclusion zone (<code>local_exclusion_zone</code>)</td><td>Informal, low-visibility, and cross-organizational uptake positions</td></tr><tr><td>Affected positions (<code>affected_positions</code>)</td><td>1. Initiators<br>2. People taking up the work<br>3. Beneficiaries<br>4. Cost bearers</td></tr></tbody></table></div><p>E. Uptake, Responsibility, Normative Status, Ceilings, and Correction</p><div class="xk-table"><table><thead><tr><th>Field</th><th>What to Record</th></tr></thead><tbody><tr><td>Uptake carriers (<code>carrier</code>)</td><td>1. Personnel and positions<br>2. Procedures<br>3. Budgets<br>4. Infrastructure</td></tr><tr><td>Responsible parties (<code>responsible_subject</code>)</td><td>1. Those responsible at each node for conduct, decisions, authorization, oversight, and remedy</td></tr><tr><td>Normative status (<code>normative_status</code>)</td><td>Effectiveness of the chain does not establish that its goal is normatively justified</td></tr><tr><td>Judgment ceiling (<code>judgment_ceiling</code>)</td><td>Up to the level of explanation or diagnosis when evidence for the whole chain is sufficient</td></tr><tr><td>Action ceiling (<code>action_ceiling</code>)</td><td>This variable produces only descriptions of chain connectivity, time lags, losses, interruptions, costs, and uptake needs. It does not authorize load reduction, resource adjustments, or trials. Any real-world adjustment separately requires C12, explicit N premises at runtime, J authorization, and O procedures</td></tr><tr><td>Counterexamples (<code>counterexamples</code>)</td><td>1. A compelling vision and concentrated mobilization lack sustained resources, maintenance, or repayment<br>2. A chain that appears connected end to end shifts key costs to people taking up work outside its boundary</td></tr><tr><td>Appeal (<code>appeal</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, people taking up work along the chain or at affected positions can challenge resources, costs, and attribution to the chain through a safe, accessible channel with anti-retaliation protection. This triggers review independent of the original judgment about the chain or the decision chain</td></tr><tr><td>Rollback (<code>rollback</code>)</td><td>Under <code>appeal_and_rollback_rule</code>, once rollback is authorized, the designated responsible party must within the stated deadline actually revoke attribution to the chain as a whole and cancel the downstream effect of that attribution, and restore descriptions at the level of individual nodes and the unresolved status. Preserve versions and verification of completion</td></tr></tbody></table></div></div>',1)])])}const b=t(i,[["render",r]]);export{h as __pageData,b as default};
